package dev.joaomendonca.agendapro.settings.api;import dev.joaomendonca.agendapro.settings.application.SettingsService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/settings") public class SettingsController{private final SettingsService service;public SettingsController(SettingsService s){service=s;}@GetMapping public SettingsResponse get(){return service.get();}@PutMapping public SettingsResponse update(@Valid @RequestBody SettingsRequest r){return service.update(r);}}
